import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));
if (mode === 'canonical') {
  check('Crème Brûlée', 'creme-brulee');
  check('Cre\u0300me Bru\u0302le\u0301e', 'creme-brulee');
  check('a\u0301\u0323b c\u0327\u0302d', 'ab-cd');
  check('  É\u0301! A\u0308?  ', 'e-a');
  let count = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const nfd = letter.normalize('NFD');
    if (!/^[A-Za-z]\p{M}+$/u.test(nfd)) continue;
    const expected = nfd[0].toLowerCase();
    check(letter, expected);
    check(nfd, expected);
    check(`X${letter}Y ${nfd}!`, `x${expected}y-${expected}`);
    count++;
  }
  assert.ok(count > 400, `only ${count} canonical cases`);
} else if (mode === 'extended') {
  const mappings = [
    ['Łł', 'll'], ['Øø', 'oo'], ['Ææ', 'aeae'], ['Œœ', 'oeoe'],
    ['ẞß', 'ssss'], ['Đđ', 'dd'], ['Ðð', 'dd'], ['Þþ', 'thth'],
    ['Ħħ', 'hh'], ['Ŧŧ', 'tt'], ['ı', 'i'], ['ſ', 's'],
    ['Ǣǣ', 'aeae'], ['Ǽǽ', 'aeae'], ['Ǿǿ', 'oo'],
    ['ﬀ', 'ff'], ['ﬁ', 'fi'], ['ﬂ', 'fl'], ['ﬃ', 'ffi'], ['ﬄ', 'ffl']
  ];
  for (const [input, expected] of mappings) {
    check(input, expected);
    check(`--${input},42--`, `${expected}-42`);
    check(input + '\u0301\u0323', expected);
  }
  check('Łódź', 'lodz');
  check('Smørrebrød Straße cœur Æsir Þór Đorđe', 'smorrebrod-strasse-coeur-aesir-thor-dorde');
  check('Łódź Москва Αθήνα 東京', 'lodz-москва-αθήνα-東京');
} else if (mode === 'regression') {
  const old = s => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  for (const input of ['', 'Hello, World!', '  --Release 2.0--  ', '---', 'A_B / C\\D', 'a😀b', '123 ٤٥٦ １２３', 'Привет мир', 'Αθήνα κόσμος', '日本語 東京', '한글 한국', '中文', 'مرحبا بالعالم', 'שלום עולם', 'ภาษาไทย', 'हिन्दी', 'ქართული', 'Հայերեն', 'a\u200db', '\nHello\tWORLD\n']) check(input, old(input));
  // Exhaustively protect non-Latin letters, including accented Greek/Cyrillic
  // and compatibility characters that global NFD/NFKD would change.
  let count = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || /^\p{Script=Latin}$/u.test(letter)) continue;
    check(letter, old(letter));
    count++;
  }
  assert.ok(count > 100000);
} else {
  throw new Error('Unknown check mode');
}
console.log(`${mode}: passed`);
